def mw_handle_target(target_text, target_format):
    """ Handles reading in a file specified in cli command.

    Args:
        target_text (str): String that specifies where 6
        target_format (str): Valid formats include `.json`, `.yml`, `.yaml`, or `.python`
    Returns:
        The content of the file that you specified
    Raises:
        CommandLineError: Issue with file format or appropriate file reading package not installed.
    """
    if not target_text:
        return {}
    target = {}
    if target_format == 'json':
        try:
            target = json.loads(target_text)
        except Exception as e:
            _error('could not load target data, got: %s' % e)
    elif target_format in ('yaml', 'yml'):
        try:
            import yaml
            try:
                target = yaml.safe_load(target_text)
            except Exception as e:
                _error('could not load target data, got: %s' % e)
        except ImportError:
            _error('No YAML package found. To process yaml files, run: pip install PyYAML')
    elif target_format == 'python':
        try:
            target = eval(target_text, {'__builtins__': __builtins__}, {})
        except Exception as e:
            _error('could not load target data from Python expression, got: %s' % e)
    elif target_format == 'python-full':
        try:
            target = eval(target_text, {'__builtins__': __builtins__}, {})
        except Exception as e:
            _error('could not load target data from Python expression, got: %s' % e)
    else:
        _error('expected target-format to be one of json, yaml, yml, python, or python-full')
    return target

